package app.lensdrop.transfer;
public final class PrintRulesTest{
 private static int count;static void check(boolean x,String name){if(!x)throw new AssertionError(name);count++;System.out.println("PASS "+name);}
 public static void main(String[] a){check(PrintRules.terminal("simulated"),"Simulation is terminal without a physical claim");check(PrintRules.terminal("operator_confirmed"),"Operator-confirmed output is terminal");check(!PrintRules.terminal("submitted_unconfirmed"),"Driver submission remains unconfirmed");check(!PrintRules.terminal("outcome_unknown"),"Uncertain output is not auto-reprinted");check(PrintRules.acceptsBytes("receiving"),"Partial LAN upload can continue");check(PrintRules.acceptsBytes("awaiting_file"),"Cloud fallback can accept bytes");check(!PrintRules.acceptsBytes("ready"),"Accepted complete jobs do not reupload");check(PrintRules.receiptMismatch("a","a","h","h",12,12,"s","s")==null,"Exact receipt accepted");check(PrintRules.receiptMismatch("a","b","h","h",12,12,"s","s")!=null,"Different job rejected");check(PrintRules.receiptMismatch("a","a","h","x",12,12,"s","s")!=null,"Different image rejected");check(PrintRules.receiptMismatch("a","a","h","h",12,13,"s","s")!=null,"Different byte count rejected");check(PrintRules.receiptMismatch("a","a","h","h",12,12,"s","other")!=null,"Different destination rejected");check(TransferLane.enter(),"First worker acquires transfer lane");check(!TransferLane.enter(),"Other worker cannot race into same lane");TransferLane.leave();check(TransferLane.enter(),"Lane released after checkpoint");TransferLane.leave();System.out.println(count+" H5 pure-Java assertions passed. Not an Android SDK build.");}
}
